//! JSON Schemas in the strict form model providers accept for structured outputs.

use schemars::JsonSchema;
use serde_json::{Map, Value};

/// A schema for `T` with references inlined, every property required, extra properties
/// forbidden, and constructs strict providers reject rewritten to equivalents.
///
/// # Panics
/// Never in practice: schemas generated by `schemars` always serialise.
#[must_use]
pub fn strict_schema<T: JsonSchema>() -> Value {
    let mut root = serde_json::to_value(schemars::schema_for!(T)).unwrap_or(Value::Null);
    let definitions = root
        .get("$defs")
        .and_then(Value::as_object)
        .cloned()
        .unwrap_or_default();
    if let Some(object) = root.as_object_mut() {
        object.remove("$defs");
        object.remove("$schema");
        object.remove("title");
    }
    normalise(&mut root, &definitions);
    root
}

/// Schema keywords whose value is a single sub-schema.
const SINGLE: [&str; 2] = ["items", "not"];
/// Schema keywords whose value is a list of sub-schemas.
const LISTS: [&str; 3] = ["anyOf", "oneOf", "allOf"];

fn normalise(value: &mut Value, definitions: &Map<String, Value>) {
    let Value::Object(object) = value else { return };

    let target = object
        .get("$ref")
        .and_then(Value::as_str)
        .and_then(|reference| reference.strip_prefix("#/$defs/"))
        .and_then(|name| definitions.get(name))
        .cloned();
    if let Some(mut target) = target {
        if let (Some(description), Some(fields)) =
            (object.get("description").cloned(), target.as_object_mut())
        {
            fields.insert("description".into(), description);
        }
        *value = target;
        normalise(value, definitions);
        return;
    }

    // `properties` maps field names to schemas; recurse into the values, never the map itself.
    if let Some(Value::Object(fields)) = object.get_mut("properties") {
        for schema in fields.values_mut() {
            normalise(schema, definitions);
        }
    }
    for keyword in SINGLE {
        if let Some(schema) = object.get_mut(keyword) {
            normalise(schema, definitions);
        }
    }
    for keyword in LISTS {
        if let Some(Value::Array(schemas)) = object.get_mut(keyword) {
            for schema in schemas {
                normalise(schema, definitions);
            }
        }
    }

    object.remove("format");
    object.remove("title");
    if let Some(variants) = object.remove("oneOf") {
        object.insert("anyOf".into(), variants);
    }
    collapse_string_enum(object);
    if let Some(properties) = object.get("properties").and_then(Value::as_object) {
        let keys: Vec<Value> = properties
            .keys()
            .map(|k| Value::String(k.clone()))
            .collect();
        object.insert("required".into(), Value::Array(keys));
        object.insert("additionalProperties".into(), Value::Bool(false));
    }
}

/// `anyOf: [{const: "a"}, {const: "b"}]` becomes `{type: "string", enum: ["a", "b"]}`.
fn collapse_string_enum(object: &mut Map<String, Value>) {
    let Some(variants) = object.get("anyOf").and_then(Value::as_array) else {
        return;
    };
    let constants: Option<Vec<Value>> = variants
        .iter()
        .map(|v| v.get("const").filter(|c| c.is_string()).cloned())
        .collect();
    if let Some(values) = constants.filter(|c| !c.is_empty()) {
        object.remove("anyOf");
        object.insert("type".into(), Value::String("string".into()));
        object.insert("enum".into(), Value::Array(values));
    }
}

#[cfg(test)]
mod tests {
    use serde::Deserialize;
    use serde_json::json;

    use super::*;

    #[derive(Deserialize, JsonSchema)]
    #[allow(dead_code)]
    enum Kind {
        /// First.
        Alpha,
        /// Second.
        Beta,
    }

    #[derive(Deserialize, JsonSchema)]
    #[allow(dead_code)]
    struct Inner {
        value: f32,
    }

    #[derive(Deserialize, JsonSchema)]
    #[allow(dead_code)]
    struct Outer {
        kind: Kind,
        inner: Inner,
        maybe: Option<Inner>,
        list: Vec<Inner>,
    }

    #[derive(Deserialize, JsonSchema)]
    #[allow(dead_code)]
    struct Tricky {
        /// A field that happens to share a name with a schema keyword.
        properties: Vec<Inner>,
        items: Inner,
    }

    #[test]
    fn fields_named_like_schema_keywords_are_not_mistaken_for_keywords() {
        let schema = strict_schema::<Tricky>();
        let fields = schema["properties"].as_object().unwrap();
        assert_eq!(
            fields.keys().map(String::as_str).collect::<Vec<_>>(),
            ["items", "properties"]
        );
        assert_eq!(schema["required"], json!(["items", "properties"]));
        assert_eq!(fields["properties"]["type"], "array");
        assert_eq!(fields["properties"]["items"]["additionalProperties"], false);
        assert_eq!(fields["items"]["properties"]["value"]["type"], "number");
    }

    #[test]
    fn inlines_references_and_drops_definitions() {
        let schema = strict_schema::<Outer>();
        assert!(!schema.to_string().contains("$ref"), "{schema}");
        assert!(schema.get("$defs").is_none());
        assert_eq!(
            schema["properties"]["inner"]["properties"]["value"]["type"],
            "number"
        );
    }

    #[test]
    fn requires_every_property_and_forbids_extras_at_every_level() {
        let schema = strict_schema::<Outer>();
        assert_eq!(schema["additionalProperties"], false);
        let required: Vec<&str> = schema["required"]
            .as_array()
            .unwrap()
            .iter()
            .filter_map(Value::as_str)
            .collect();
        for key in ["kind", "inner", "maybe", "list"] {
            assert!(required.contains(&key), "{key}");
        }
        assert_eq!(schema["properties"]["inner"]["additionalProperties"], false);
        assert_eq!(
            schema["properties"]["list"]["items"]["additionalProperties"],
            false
        );
    }

    #[test]
    fn unit_enums_become_plain_string_enums() {
        let schema = strict_schema::<Outer>();
        assert_eq!(schema["properties"]["kind"]["type"], "string");
        assert_eq!(
            schema["properties"]["kind"]["enum"],
            json!(["Alpha", "Beta"])
        );
    }

    #[test]
    fn strips_numeric_formats_providers_reject() {
        assert!(!strict_schema::<Outer>().to_string().contains("\"format\""));
    }

    #[test]
    fn optional_fields_stay_nullable() {
        let schema = strict_schema::<Outer>();
        assert!(
            schema["properties"]["maybe"].to_string().contains("null"),
            "{schema}"
        );
    }
}
